practice.starter:
def logic(expr, values):
    # your code
    pass

practice.solution:
def logic(expr, values):
    if isinstance(expr, str):
        return values[expr]
    op = expr[0]
    args = [logic(e, values) for e in expr[1:]]
    if op == 'not':
        return 1 - args[0]
    if op == 'and':
        return 1 if all(args) else 0
    if op == 'or':
        return 1 if any(args) else 0
    if op == 'xor':
        return args[0] ^ args[1]
    if op == 'nand':
        return 0 if all(args) else 1
    return 0

